/**
 * Provider-neutral object storage port. Application services depend on this,
 * never on an SDK, so another S3-compatible provider (for example MinIO) can be
 * used without changing document logic.
 *
 * Object keys are always generated by trusted backend code. Keys are not an
 * authorization mechanism: callers must authorize before using this port.
 */
export const OBJECT_STORAGE = Symbol('OBJECT_STORAGE');

export interface IPresignedUploadRequest {
  key: string;
  contentType: string;
  contentLength: number;
  /** Base64 SHA-256 of the body. The provider rejects a body that differs. */
  checksumSha256Base64: string;
  expiresInSeconds: number;
}

export interface IPresignedUpload {
  url: string;
  method: 'PUT';
  /** Headers the client must send unchanged; they are part of the signature. */
  headers: Record<string, string>;
  expiresAt: Date;
}

export interface IPresignedDownloadRequest {
  key: string;
  /** Original file name, used only for the Content-Disposition response. */
  fileName: string;
  contentType: string;
  expiresInSeconds: number;
}

export interface IPresignedDownload {
  url: string;
  expiresAt: Date;
}

export interface IStoredObjectMetadata {
  sizeBytes: number;
  contentType: string | null;
  checksumSha256Base64: string | null;
  /** Provider object version when bucket versioning is enabled. */
  versionId: string | null;
}

export interface IObjectStorage {
  /** Stable provider identifier persisted with each stored object. */
  readonly provider: string;
  readonly bucket: string;

  createUploadUrl(request: IPresignedUploadRequest): Promise<IPresignedUpload>;
  createDownloadUrl(
    request: IPresignedDownloadRequest,
  ): Promise<IPresignedDownload>;
  /** Returns null when the object does not exist. */
  headObject(key: string): Promise<IStoredObjectMetadata | null>;
  /** Reads at most the first `length` bytes (for file-signature checks). */
  readObjectPrefix(key: string, length: number): Promise<Uint8Array>;
  /** Idempotent: deleting a missing object succeeds. */
  deleteObject(key: string): Promise<void>;
}
